import pathlib,json,hashlib
r=pathlib.Path('.');sha=lambda b:hashlib.sha256(b).hexdigest()
coverage=json.load(open('changes/p99-nz-coverage/page-coverage.json'))
quests={q['zone']+'/'+q['name']:q for f in r.glob('data/quests/*.ndjson') for l in f.open() if(q:=json.loads(l))}
def proposal(id,title,key,old,new,summary):
 row=quests[key];before=row['lua_content'];assert before.count(old)==1,(key,old);after=before.replace(old,new)
 sources=list(r.glob('maintained/lua/*/'+key+'.lua'));assert len(sources)<=1
 target=str(sources[0]) if sources else 'maintained/lua/modified-upstream/'+key+'.lua'
 out=r/'changes'/id;out.mkdir(exist_ok=True);file=out/(key.replace('/','--')+'.lua');file.write_text(after)
 page=next(x for x in coverage if x['title']==title)['evidence']
 p={'format':1,'id':id,'summary':summary,'baseManifestSha256':sha((r/'manifest.json').read_bytes()),'evidence':[{'url':page['url'],'note':f"Cached {page['fetchedAt']}; revision unavailable; SHA256 {page['sha256']}. {summary} All other behavior preserved. Static source comparison only; full runtime/UI not verified."}],'rows':[{'table':'quests','before':row,'after':{**row,'lua_content':after,**({'has_say_event':1}if 'function event_say'not in before and 'function event_say'in after else{})}}],'sources':[{'target':target,'beforeSha256':sha(sources[0].read_bytes()) if sources else None,'proposedFile':str(file),'afterSha256':sha(file.read_bytes())}]}
 (r/'changes'/(id+'.json')).write_text(json.dumps(p,indent=2)+'\n')
